  ]}
};
const ctl = {}; for (const r of registry) if (r && r.agent_id) ctl[r.agent_id] = r;
const openAuto = {}, todayCnt = {};
for (const t of open) if (t.source === 'autonomous_loop' || t.source === 'news_radar') openAuto[t.assigned_to_agent] = (openAuto[t.assigned_to_agent] || 0) + 1;
for (const t of today) todayCnt[t.assigned_to_agent] = (todayCnt[t.assigned_to_agent] || 0) + 1;
const hi = news.filter(n => n && (n.impact_level === 'High' || n.impact_level === 'Critical'));
const newsCtx = news.length ? '\n\nالتحديثات الحكومية المرصودة (آخر ٣٠ ساعة، من رادار آلاء — تحقّق منها من المصدر قبل أي استخدام):\n' + news.slice(0, 8).map(n => '- [' + n.impact_level + '] ' + n.title + ' — ' + (n.summary_ar || '').slice(0, 160) + ' (' + (n.source_name || n.authority || '') + ') ' + (n.url || '')).join('\n') : '\n\nلا تحديثات حكومية مرصودة خلال ٣٠ ساعة.';
const stale = deals.filter(d => d && d.updated_at && (Date.now() - new Date(d.updated_at).getTime()) > 3 * 864e5 && !/delivered|lost|closed/i.test(String(d.stage || '')));
const dealsCtx = '\nالصفقات: ' + deals.length + ' إجمالاً، ' + stale.length + ' لم تتحرّك منذ ٣ أيام' + (stale.length ? ': ' + stale.slice(0, 5).map(d => (d.client_name || d.deal_id) + ' (' + d.stage + ', ' + (d.deal_owner || '') + ')').join('، ') : '') + '.';
const out = [];
const iso = now.toISOString();
for (const [agent, cfg] of Object.entries(P)) {
  const c = ctl[agent] || {};
  const st = String(c.status || '').toLowerCase();
  if (c.enabled === false || ['paused', 'maintenance', 'disabled', 'offline'].includes(st)) continue;
  if ((openAuto[agent] || 0) >= 1) continue;
  if ((todayCnt[agent] || 0) >= 3) continue;
  let pick = null, tag = '';
  if (slot) { const idx = (doy * 2 + (slot === 'A' ? 0 : 1)) % cfg.book.length; pick = cfg.book[idx]; tag = slot; }
  else if (hi.length && /التحديثات|الأخبار|زاتكا|العقار|الإقامة|التوطين/.test(cfg.book.map(b => b[0]).join(' ')) && (todayCnt[agent] || 0) < 2) {
    pick = cfg.book.find(b => /التحديثات|الأخبار|زاتكا|العقار|الإقامة|التوطين/.test(b[0])) || null; tag = 'SIG';
  }
  else if (agent === 'badr_sales' && stale.length) { pick = cfg.book[1]; tag = 'SIG'; }
  if (!pick) continue;
  const task_id = 'AUTO-' + agent.toUpperCase() + '-' + ymd + '-' + tag;
  if (today.some(t => t.task_id === task_id) || open.some(t => t.task_id === task_id)) continue;
  out.push({ json: {
    task_id, parent_task_id: '', source: 'autonomous_loop', company_id: 'business-partner', client_name: 'Business Partner', channel: 'internal',
    objective: cfg.name + ' — ' + pick[0],
    context: 'مهمة ذاتية من فرح (النبض الذاتي، ' + (tag === 'SIG' ? 'إشارة حيّة' : 'جولة ' + tag) + '). ' + pick[1] + '\n\n' + EVIDENCE + COLLAB + REPORT + dealsCtx + newsCtx,
    created_by_agent: 'farah_chief_of_staff', assigned_to_agent: agent,
    priority: tag === 'SIG' && hi.some(n => n.impact_level === 'Critical') ? 'P1' : 'P2',
    status: 'queued', approval_required: false, approval_status: 'not_required',
    next_action: 'Execute with your tools, consult the needed director, report result + exact next step.',
    created_at: iso, updated_at: iso, revenue_value: 0, cash_stage: cfg.cash, human_action_required: false, blocked_by: ''
  } });
}
return out;
